package main

import (
	"fmt"
	"strings"

	lua "github.com/yuin/gopher-lua"
)

// ExecutePricingScript executes a user-provided Lua script to calculate the final price
// of a product based on the given context.
func ExecutePricingScript(script string, ctx map[string]float64) (float64, error) {
	// Security: Restrict dangerous functions and modules in the Lua environment
	// We create a sandboxed environment by limiting what's available in the global scope

	// Create a new Lua state
	L := lua.NewState()
	defer L.Close()

	// Remove potentially dangerous functions from the global environment
	// This helps prevent code injection attacks through Lua scripts
	dangerousFuncs := []string{
		"os",       // OS module - can execute system commands
		"io",       // IO module - can read/write files
		"dofile",   // Can load and execute external files
		"loadfile", // Can load external files
		"load",     // Can compile and execute arbitrary strings
		"loadstring", // Deprecated but still present in some versions
	}

	for _, fn := range dangerousFuncs {
		L.SetGlobal(fn, lua.LNil)
	}

	// Also remove the 'os' table entirely if it exists
	osTable := L.GetGlobal("os")
	if osTable.Type() == lua.LTTable {
		// Clear all fields in the os table
		table := osTable.(*lua.LTable)
		table.ForEach(func(k lua.LValue, v lua.LValue) {
			L.SetField(table, k.String(), lua.LNil)
		})
	}

	// Load and execute the script
	if err := L.DoString(script); err != nil {
		return 0, fmt.Errorf("failed to execute Lua script: %w", err)
	}

	// Get the calculate_final_price function from global scope
	fn := L.GetGlobal("calculate_final_price")
	if fn.Type() != lua.LTFunction {
		return 0, fmt.Errorf("calculate_final_price is not a function or not defined")
	}

	// Convert Go context map to Lua table
	ctxTable := L.NewTable()
	for k, v := range ctx {
		// Sanitize key names to prevent injection via table keys
		sanitizedKey := sanitizeLuaKey(k)
		if sanitizedKey == "" {
			continue
		}
		L.SetField(ctxTable, sanitizedKey, lua.LNumber(v))
	}

	// Call the function with the context table
	if err := L.CallByParam(lua.P{
		Fn:      fn,
		NRet:    1,
		Protect: true,
	}, ctxTable); err != nil {
		return 0, fmt.Errorf("failed to call calculate_final_price: %w", err)
	}

	// Get the result from the Lua stack
	result := L.Get(-1)
	L.Pop(1) // Remove the result from the stack

	// Convert result to float64
	if result.Type() != lua.LTNumber {
		return 0, fmt.Errorf("calculate_final_price did not return a number")
	}

	finalPrice := float64(result.(lua.LNumber))

	// Validate that the price is reasonable (non-negative and within bounds)
	if finalPrice < 0 {
		return 0, fmt.Errorf("calculated price cannot be negative")
	}

	// Prevent excessively large values that could cause issues
	if finalPrice > 1e15 {
		return 0, fmt.Errorf("calculated price exceeds maximum allowed value")
	}

	return finalPrice, nil
}

// sanitizeLuaKey ensures that the key is safe to use in Lua
// It only allows alphanumeric characters and underscores
func sanitizeLuaKey(key string) string {
	var sb strings.Builder
	for _, r := range key {
		if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || r == '_' {
			sb.WriteRune(r)
		}
	}
	return sb.String()
}

